	function parseChangelog(md, fromVersion, toVersion) {
		const sectionRegex = /##\s+(.+?)\r?\n([\s\S]*?)(?=##\s+|\s*$)/g;
		const sections = [];
		let m;
		while ((m = sectionRegex.exec(md)) !== null) {
			const version = m[1].trim();
			const items = m[2].trim().split(/\r?\n/).map((l) => l.replace(/^[-*]\s*/, "").trim()).filter(Boolean);
			sections.push({
				version,
				items
			});
		}
		const fromIdx = sections.findIndex((s) => s.version === fromVersion);
		const toIdx = sections.findIndex((s) => s.version === toVersion);
		if (toIdx === -1) return [];
		const start = toIdx;
		let end;
		if (fromIdx !== -1) end = Math.min(fromIdx - 1, sections.length - 1);
		else {
			end = sections.length - 1;
			for (let i = toIdx; i < sections.length; i++) {
				const pa = sections[i].version.split(".").map(Number);
				const pb = fromVersion.split(".").map(Number);
				let le = true;
				for (let j = 0; j < 3; j++) {
					if ((pa[j] || 0) > (pb[j] || 0)) {
						le = false;
						break;
					}
					if ((pa[j] || 0) < (pb[j] || 0)) {
						le = true;
						break;
					}
				}
				if (le) {
					end = i - 1;
					break;
				}
			}
		}
		const result = [];
		for (let i = start; i <= end; i++) result.push({
			title: sections[i].version,
			items: sections[i].items
		});
		return result;
	}
