		keybindManager(event) {
			const key = event.key.toLowerCase();
			if (!event.ctrlKey) return;
			if (key != "b" && key != "i" && key != "d" && (key != "k" || !event.shiftKey)) return;
			const elem = document.querySelector(`textarea[class^="TextInput-"]`);
			if (!elem || document.activeElement != elem) return;
			console.log("wawa prevented", key);
			event.preventDefault();
			const start = elem.selectionStart ?? 0;
			const end = elem.selectionEnd ?? 0;
			const text = elem.value;
			let lineStart = text.lastIndexOf("\n", start - 1) + 1;
			const lineEndIndex = text.indexOf("\n", end);
			const lineEnd = lineEndIndex === -1 ? text.length : lineEndIndex;
			const selectedText = text.substring(start, end);
			let placeholder = "";
			if (key == "b") placeholder = `<b>${selectedText}</b>`;
			if (key == "i") placeholder = `<i>${selectedText}</i>`;
			if (key == "d") {
				const currentLine = text.substring(lineStart, lineEnd);
				console.log(currentLine);
				placeholder = `\n${currentLine}`;
				elem.setSelectionRange(lineEnd, lineEnd);
			}
			if (key == "k") {
				if (lineEndIndex === -1 && lineStart > 0) lineStart -= 1;
				console.log(lineEnd, lineStart);
				elem.setSelectionRange(lineStart - 1, lineEnd);
			}
			const cursorPos1 = selectedText.length > 0 ? start + placeholder.length : start + 3;
			const cursorPos2 = selectedText.length > 0 ? start + placeholder.length : start + 3;
			elem.focus();
			if (!document.execCommand("insertText", false, placeholder)) {
				if (key == "k") elem.value = text.substring(0, lineStart) + text.substring(lineEnd);
				elem.value = text.substring(0, start) + placeholder + text.substring(end);
			}
			if (key == "d") elem.setSelectionRange(start + placeholder.length, end + placeholder.length);
			else if (key == "k") elem.setSelectionRange(lineStart, lineStart);
			else elem.setSelectionRange(cursorPos1, cursorPos2);
		}
